'use strict';
({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    const CONCEPT_SCREENING_DATE_UUID = "6c228403-94bc-5ddd-a0f9-17d4b3b9c8a5";

    const selectedDate = encounter.getObservationValue(CONCEPT_SCREENING_DATE_UUID);

    if(selectedDate) {
        const selectedMoment = moment(selectedDate).startOf('day');
        const today = moment().startOf('day');
        if (selectedMoment.isAfter(today)) {
            validationErrors.push("Selected date cannot be in the future")
        }
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

