'use strict';
({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    let questionGroupIndex = params.questionGroupIndex;
    const CONCEPT_RELATIVES_WITH_CANCER_UUID = "432a0a40-9aea-5640-8558-ca7764122eb4";
    const CONCEPT_RELATIVE_RELATIONSHIP_UUID = "ef4b750e-b745-5769-af9b-8bb5e65fe4f7";
    const CONCEPT_RELATIVE_DEGREE_UUID = "792df5bb-d0dd-508a-a2e0-d5e4b2afc2c2";
    const ANSWER_FIRST_DEGREE_UUID = "ff359d77-8cb8-5fea-9ade-5b65ced80b45";
    const ANSWER_SECOND_DEGREE_UUID = "dad23dd7-f359-5d66-85d5-7f3a15cf7b59";
    const ANSWER_OTHER_DEGREE_UUID = "e6c5f249-e143-55c5-a3a2-b19e44f1e83d";
    const ANSWER_UNKNOWN_DEGREE_UUID = "5e7d6184-15dd-5ab2-8a22-6e0f27416248";
    const DEGREES = {"Mother": ANSWER_FIRST_DEGREE_UUID, "Father": ANSWER_FIRST_DEGREE_UUID, "Sister": ANSWER_FIRST_DEGREE_UUID,
        "Brother": ANSWER_FIRST_DEGREE_UUID, "Daughter": ANSWER_FIRST_DEGREE_UUID, "Son": ANSWER_FIRST_DEGREE_UUID,
        "Grandmother": ANSWER_SECOND_DEGREE_UUID, "Grandfather": ANSWER_SECOND_DEGREE_UUID, "Aunt": ANSWER_SECOND_DEGREE_UUID,
        "Uncle": ANSWER_SECOND_DEGREE_UUID, "Other": ANSWER_OTHER_DEGREE_UUID, "Don't know": ANSWER_UNKNOWN_DEGREE_UUID};

    const questionGroup = encounter.getObservationValue(CONCEPT_RELATIVES_WITH_CANCER_UUID);

    if (questionGroup && questionGroupIndex < questionGroup.length) {
        const relationship = questionGroup[questionGroupIndex].findObservationByConceptUUID(CONCEPT_RELATIVE_RELATIONSHIP_UUID);
        const recordedDegree = questionGroup[questionGroupIndex].findObservationByConceptUUID(CONCEPT_RELATIVE_DEGREE_UUID);
        if (relationship) {
            const degree = DEGREES[relationship.getReadableValue()];
            if (!recordedDegree || recordedDegree.getValue() != degree) {
                value = degree;
            }
        }
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

