            inputs.relative_relation = 'second';
        } else if (relativeDegrees.length > 0) {
            inputs.relative_relation = 'dk';
        }
        if (_.intersection(relativeCancerTypes, RELATED_CANCERS).length > 0) {
            inputs.relative_type = 'related';
        } else if (_.intersection(relativeCancerTypes, OTHER_CANCERS).length > 0) {
            inputs.relative_type = 'other';
        } else if (relativeCancerTypes.length > 0) {
            inputs.relative_type = 'dk';
