        const patientId = encounter.individual.getObservationReadableValue(CONCEPT_PATIENT_ID_UUID);
        if (patientId) {
            const encounters = encounter.individual.getEncounters() || [];
            const previousEncounters = encounters.filter(enc => enc.encounterType.name == "Breast Cancer Screening" && enc.uuid != encounter.uuid && enc.encounterDateTime != null);
            let sequence = previousEncounters.length;
            previousEncounters.forEach(enc => {
                const previousId = enc.getObservationReadableValue(CONCEPT_ENCOUNTER_ID_UUID);
                if (previousId) {
                    const match = previousId.match(/(\d+)\s*$/);
                    if (match && parseInt(match[1], 10) > sequence) {
                        sequence = parseInt(match[1], 10);
                    }
                }
            });
            encounterId = patientId + "BCS" + String(sequence + 1).padStart(3, "0");
        }
    }

    if (encounterId) {
        encounterDecisions.push({name: "Encounter ID", value: encounterId});
    }

    if (riskInputsAnswered) {
        encounterDecisions.push({name: "PS Risk Raw Score", value: riskRawScore});
        encounterDecisions.push({name: "PS Risk Probability", value: riskProbability});
        encounterDecisions.push({name: "PS Risk Class", value: [riskClass]});
        encounterDecisions.push({name: "PS Risk Model", value: riskModel});
    }

    decisions.enrolmentDecisions.push(...enrolmentDecisions);
    decisions.encounterDecisions.push(...encounterDecisions);
    decisions.registrationDecisions.push(...registrationDecisions);
    return decisions;
};

visitScheduleRule:
"use strict";
({ params, imports }) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const scheduleBuilder = new imports.rulesConfig.VisitScheduleBuilder({encounter});

    const CONCEPT_REFER_FOR_BREAST_CARE_UUID = "23037bc5-26c5-5309-9b27-2d4af30fc278";
    const encounterType = "Breast Cancer Referral";

    const referred = encounter.getObservationReadableValue(CONCEPT_REFER_FOR_BREAST_CARE_UUID) == 'Yes';
    const alreadyScheduled = encounter.individual.getEncounters().some(enc => enc.voided == false && enc.encounterType.name == encounterType && enc.encounterDateTime == null && enc.cancelDateTime == null);

    if (referred && !alreadyScheduled) {
        const earliestDate = moment(encounter.encounterDateTime).startOf('day').toDate();
        const maxDate = moment(earliestDate).add(7, 'days').endOf('day').toDate();
        scheduleBuilder.add({name: encounterType, encounterType: encounterType, earliestDate, maxDate});
    }

    return scheduleBuilder.getAll();
};
